/* Lines added after the first translation: home lines for the more traditions, practice-room questions, and place details. */
{
const addTo = (sec, id, o) => Object.assign(FEEL_EN[sec][id] = FEEL_EN[sec][id] || {}, o);

addTo("make", "star", { home: "Hang a star in a window at home too, and each day until Christmas, look at it and pray briefly for someone." });
addTo("make", "manger", { home: "Set out an empty stable at home too, and lay the baby Jesus in it together as a family on Christmas morning." });
addTo("make", "nicholas", { home: "Draw names in the family and do small kindnesses for each other in secret until Christmas." });
addTo("make", "lucia", { home: "On the evening of the shortest day, turn off the lights, keep one small lamp on, and pray together as a family.", q: "I've been feeling down for a long time. Is it because my faith is weak?" });
addTo("make", "vasilopita", { home: "At the first meal of the new year, set aside the first portion and decide together whom to share it with." });
addTo("make", "starsingers", { home: "Put the new year and a one-line blessing on the inside of your front door, and pray for everyone who comes and goes through it." });
addTo("make", "questions", { home: "At dinner, let your child ask one thing they wonder about, and before answering, ask them first, 'What do you think?'" });
addTo("make", "animals", { home: "Say a short prayer of thanks together for your pet or a favorite animal.", q: "My dog died. Did my dog go to heaven?" });
addTo("make", "thanks", { home: "For a week, at every dinner, have each person share one thing they were thankful for that day." });
addTo("make", "pretzel", { home: "Bake or buy pretzels at home, and before eating, fold your arms and say a short prayer.", q: "I prayed every day, but Mom and Dad fought again. Doesn't God listen to my prayers?" });
addTo("make", "palm", { home: "Hang the palm branch by the front door, and during Holy Week read one part of the story of Jesus' last week each day." });
addTo("make", "handwash", { home: "In the evening, wash each other's hands as a family and each share one thing you were thankful for today." });
addTo("make", "garden", { home: "Plant sprouting seeds in a pot and watch them come up together until Easter." });
addTo("make", "pinwheel", { home: "On a windy day, take a walk with the pinwheel and talk about God, who is with us though we can't see him." });
addTo("make", "tongues", { home: "Think of a neighbor from another country, and learn a greeting in their language together as a family.", q: "My best friend is Muslim. Will my friend go to hell?" });
addTo("make", "illum", { home: "Put the verse your child decorated where everyone can see it, and read it aloud together.", q: "Second Samuel and First Chronicles tell the same story with different numbers. So is the Bible wrong?" });
addTo("make", "creation", { home: "Take a walk near home and have each person find one thing God made and take a photo of it.", q: "They say the earth is 4.6 billion years old. So is the Bible wrong about the six days?" });
addTo("make", "treasure", { home: "Bring out one old thing at home (a family Bible, a wedding album) and tell your child its story." });

addTo("places", "ganghwa", {
  feel: "Consecrated in 1900 by Charles John Corfe, the first Anglican bishop in Korea, as the Church of St. Peter and St. Paul. A master carpenter who built royal palaces led the work. Outside it is a traditional Korean hanok; inside it runs long like a Western church. It became a national Historic Site in 2001.",
  kids: "'It looks like a temple, but it's a church!' Find the cross on the tiled roof. The grounds follow the shape of a ship, a picture of the ark that saves the world. Where is the bow? Look for the eight Chinese characters carved on the stone font, too.",
  care: "Avoid times of worship and events, and look around quietly inside. Inside this Anglican church are a cross with the figure of Jesus and statues of saints. If children ask, explain that church buildings look a little different from church to church."
});
addTo("places", "yangnim", { with: "Walk the lanes of Yangnim-dong, where old missionary houses still stand.", care: "This is a cemetery. With young children, talk about death and remembering before you go.", q: "My grandma didn't go to church, and she died. Is she in hell?" });
addTo("places", "macau", { with: "St. Anthony's Church, with the wooden statue of Father Kim Dae-geon, and Camões Garden are within walking distance.", q: "My mom goes to the Catholic church. Does that mean she won't be saved?" });
addTo("places", "colmar", { keep: "The one part of the altarpiece you looked at longest", with: "The 'Little Venice' quarter, with old houses along the canal, is close by.", q: "Why doesn't God heal sick people?" });
addTo("places", "potsdam", { kids: "In front of the painting, find Thomas's finger and the lines on his forehead for yourself.", keep: "A photo of the painting card next to the real painting", with: "Sanssouci Palace and its large park are right there." });
addTo("places", "sagrada", { keep: "A group photo in the light from the colored glass", care: "Construction is still going on, so the areas open to visitors may change." });
}

