FEEL_EN.borrow = {
  nicholas: ["Secret Angel Sunday", "Love that gives quietly without drawing attention to itself. Jesus taught that when we give, our left hand shouldn't know what our right hand is doing.", "Keeping it as a saint's day, dressing up in a bishop's robes, the Santa story that only good children get presents", "On the first Sunday of Advent, draw names, and until Christmas give the friend you drew secret notes of encouragement and small snacks. On Christmas Sunday, reveal your 'secret angels,' and introduce Nicholas briefly as an early church leader whose story became the root of Santa."],
  lucia: ["Light Service on the Longest Night", "The light that comes when the darkness is longest. John's Gospel introduces Jesus as the light that shines in the darkness.", "Keeping it as a saint's day, crowns of candles worn on the head, choosing just one child to be Lucia", "On an evening near the winter solstice, children walk into the darkened sanctuary carrying LED candles and singing songs about light. Everyone becomes a light-bearer, and afterward you share yellow buns or tangerines."],
  vasilopita: ["First Bread of the New Year", "Giving the first share of the new year to your neighbors first", "The idea that finding the coin brings good luck for the year (it can look like a game of wishing for fortune), coins baked into the bread", "At snack time on the first Sunday of the year, break off the first piece of a big loaf for your neighbors and put it in a basket. The child who finds the star sticker under a plate becomes the 'sharing messenger' who takes the basket to an elder."],
  starsingers: ["Children's New Year Visit Songs", "Footsteps that carry good news to neighbors, and children helping other children", "Writing on doorframes in chalk (it can look like a charm), going house to house collecting money", "When the church makes its New Year home visits, children come along with paper stars and offer a song and a handwritten blessing card with a Bible verse. Instead of collecting offerings, decide together where to send the pocket money the children have saved."],
  questions: ["The Question Table", "The wisdom of treating questions as doors that open a story, not things to shut down", "Reenacting the Passover meal (seder), calling the event 'Passover,' setting out Jewish foods", "At snack time during Holy Week, start with 'Why is today special?' and tell the story of the Last Supper. Each child writes one question on a card, and before answering, the teacher first asks, 'What do you think?'"],
  animals: ["Thanks for Living Things Sunday", "The confession that every living thing God made is precious", "Keeping it as the feast day of a saint (Francis of Assisi), a blessing ritual for the animals themselves", "On a Sunday in autumn, children bring photos of their pets or favorite animals to introduce, and together you thank God, who made all living things. Listen, too, to children whose pets have died."],
  martin: ["Lantern Walk of Sharing", "Like the story of the cloak cut in half: sharing lights up the darkness", "Keeping it as a saint's day", "On a November evening, walk around the church with handmade lanterns, then deliver the winter clothes you collected. Add the story of Martin Luther, who was baptized on this day and named after the saint, and it connects to Reformation Sunday."],
  manger: ["Filling the Empty Manger", "Waiting for the baby Jesus by filling the empty space week by week", "A baby Jesus figure (some churches don't make images of Christ)", "Set out an empty manger on the first Sunday of Advent, and each week add straw, sheep, and shepherds. On Christmas morning, in the baby Jesus' place you can lay a card with the words that a Savior has been born, or a small light, instead of a figure."],
  honey: ["The Day the Word Is Sweet", "The memory that the first step of learning God's word is sweet. The Psalms sing that God's word is sweeter than honey.", "Copying a Jewish ritual as it is", "On the first Sunday of a new school term, each child gets a card with the first Bible verse to memorize and tastes a drop of honey on its first letter, along with the psalm that calls God's word sweeter than honey."],
  alleluia: ["The Alleluia Box", "The restraint of Lent and the joy that bursts out on Easter morning", "The liturgical rule of leaving 'alleluia' out of worship during Lent", "On the Sunday before Lent, children put the 'Alleluia' banners they decorated into a box and keep it in the classroom. On Easter morning, open the box and shout together. Keep your order of worship the way your church does it."],
  sukkot: ["Thanksgiving Shelter Camp", "Thanks to God, who was with his people even in the wilderness", "The name of the Feast of Tabernacles and the idea of keeping the feast", "Around Thanksgiving, build a shelter in the churchyard, eat dinner in it, and share the year's thanks. Talk together, too, about how the Old Testament feasts are shadows that point to Christ."]
};

